CREATE DATABASE IF NOT EXISTS lapaire_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;USE lapaire_db;
CREATE TABLE branches(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,city VARCHAR(80) NOT NULL,address VARCHAR(255) NOT NULL,phone VARCHAR(40) NOT NULL,email VARCHAR(140) NOT NULL,hours VARCHAR(160) NOT NULL,active TINYINT(1) DEFAULT 1);
CREATE TABLE products(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,category VARCHAR(60) NOT NULL,price DECIMAL(10,2) NOT NULL,shape VARCHAR(60),material VARCHAR(60),color VARCHAR(60),image VARCHAR(255) NULL,description TEXT,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE appointments(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,full_name VARCHAR(120) NOT NULL,email VARCHAR(140) NOT NULL,phone VARCHAR(40) NOT NULL,branch_id INT NULL,appointment_date DATE NOT NULL,appointment_time TIME NOT NULL,status ENUM('Pending','Confirmed','Completed','Cancelled') DEFAULT 'Pending',appt_notif_seen TINYINT(1) DEFAULT 0,admin_note VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL);
CREATE TABLE enquiries(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,full_name VARCHAR(120) NOT NULL,email VARCHAR(140) NOT NULL,phone VARCHAR(40),subject VARCHAR(160) NOT NULL,message TEXT NOT NULL,admin_reply TEXT NULL,replied_at DATETIME NULL,reply_seen TINYINT(1) DEFAULT 0,status ENUM('New','Read','Closed') DEFAULT 'New',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE posts(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,excerpt VARCHAR(300) NOT NULL,image VARCHAR(255) NULL,body TEXT NOT NULL,published TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE admins(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(80) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,display_name VARCHAR(100) NOT NULL);
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(120) NOT NULL,email VARCHAR(140) UNIQUE NOT NULL,phone VARCHAR(40),password_hash VARCHAR(255) NOT NULL,status ENUM('Pending','Active','Suspended') DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE wishlist(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,product_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_user_product(user_id,product_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
